"""matplotlib.pylab — legacy "import everything" namespace.

Mirrors upstream's `from numpy import *; from matplotlib.pyplot import *`
so `from pylab import *` lights up the MATLAB-style namespace. We do
not pull in `matplotlib.mlab` (deprecated upstream) or `matplotlib.dates`
beyond what `pyplot` already re-exports; if scripts need those they
should import them directly.
"""

from numpy import *  # noqa: F401, F403
from matplotlib.pyplot import *  # noqa: F401, F403
from matplotlib.pyplot import (  # noqa: F401 — re-export for star-impor safety
    plot, scatter, bar, barh, hist, pie, fill, fill_between, fill_betweenx,
    contour, contourf, imshow, pcolor, pcolormesh, errorbar, boxplot,
    violinplot, stem, step, stairs, stackplot, streamplot, quiver, hexbin,
    matshow, spy, tripcolor, tricontour, tricontourf, triplot, hlines,
    vlines, axhline, axvline, axhspan, axvspan, axline, arrow, broken_barh,
    eventplot, annotate, text, figtext, title, suptitle, xlabel, ylabel,
    xlim, ylim, xticks, yticks, xscale, yscale, grid, legend, colorbar,
    figure, subplot, subplots, subplot2grid, subplot_mosaic, subplots_adjust,
    savefig, show, close, clf, cla, axis, axes, gca, gcf, sca, sci, gci,
    autoscale, margins, tight_layout, ioff, ion, isinteractive, pause,
    rc, rcdefaults, rc_context, set_cmap, get_cmap, switch_backend,
    twinx, twiny, tick_params, ticklabel_format, minorticks_on, minorticks_off,
    locator_params, draw, draw_if_interactive,
    viridis, inferno, plasma, magma, cividis, jet, hot, cool, gray, bone,
    pink, spring, summer, autumn, winter, hsv, flag, prism, copper, nipy_spectral,
)

# Common numpy-as-np shorthand for pylab compatibility.
import numpy as np  # noqa: F401
import matplotlib as mpl  # noqa: F401
from matplotlib import pyplot as plt  # noqa: F401


# ─── Added: builtin re-exports from upstream pylab.py ──────────────


# Upstream pylab re-exports Python builtins so ``from matplotlib.pylab
# import *`` doesn't accidentally shadow them with numpy versions of
# the same name (numpy.max would shadow builtins.max otherwise). We
# follow the same convention.

abs   = abs    # noqa: A001
bool  = bool   # noqa: A001
bytes = bytes  # noqa: A001
max   = max    # noqa: A001
min   = min    # noqa: A001
pow   = pow    # noqa: A001
round = round  # noqa: A001
